from pathlib import Path
import base64,json,html
from PIL import Image,ImageDraw,ImageFont

HERE=Path(__file__).resolve().parent
ROOT=HERE.parents[1]
IMG=HERE/'images'
FONT='C:/Windows/Fonts/msyh.ttc'
def font(n):return ImageFont.truetype(FONT,n)
def stamp(name, boxes):
    im=Image.open(IMG/name).convert('RGB');d=ImageDraw.Draw(im)
    for number,box in boxes:
        x,y,x2,y2=box;d.rounded_rectangle(box,radius=7,outline='#dc6940',width=4)
        d.ellipse((x-14,y-18,x+20,y+16),fill='#dc6940')
        d.text((x+3,y-2),str(number),font=font(21),fill='white',anchor='mm')
    out=name.replace('.jpg','-marked.jpg');im.save(IMG/out,quality=92);return out
stamp('01-reference.jpg',[(1,(1017,180,1148,219)),(2,(48,350,389,391)),(3,(398,350,742,391)),(4,(751,350,1060,391))])
stamp('02-parts.jpg',[(1,(53,410,223,702)),(2,(627,363,940,402)),(3,(984,525,1210,602)),(4,(45,920,1220,964))])
stamp('03-pose.jpg',[(1,(987,414,1077,453)),(2,(984,555,1208,703)),(3,(984,707,1212,784)),(4,(45,948,1220,994))])
stamp('04-export.jpg',[(1,(985,505,1160,546)),(2,(985,548,1160,587)),(3,(985,591,1211,671)),(4,(45,893,1220,942))])

# Educational overlay on the actual accepted source frame, not a generated image.
study=ROOT/'spine_samples/video_motion_study_20261119'
s=json.loads((study/'motion_annotations.json').read_text(encoding='utf8'))['samples'][0]
source=Image.open(study/'pixel_sync_20261120/reference_frames/0063.png').convert('RGB')
im=Image.new('RGB',(1420,900),'#f4f6f1');d=ImageDraw.Draw(im)
d.text((45,25),'14 个标注点：在原帧中统一定义位置',font=font(30),fill='#183f35')
d.text((45,72),'示例：已验收第63帧；肩髋与肘膝含推定位置，不代表视频直接测得的真实关节。',font=font(20),fill='#65746e')
im.paste(source.crop((250,0,620,480)).resize((555,720)),(350,135))
items=[('neck','颈部'),('pelvis','骨盆中心'),('shoulder_near','近侧肩'),('shoulder_far','远侧肩'),('hip_near','近侧髋'),('hip_far','远侧髋'),('hand_near','近侧手端'),('hand_far','远侧手端'),('foot_near','近侧脚端'),('foot_far','远侧脚端'),('arm_near','近侧肘'),('arm_far','远侧肘'),('leg_near','近侧膝'),('leg_far','远侧膝')]
for i,(key,label) in enumerate(items,1):
    q=s['points'].get(key) or s['chains'][key]['joint'];x=350+(q[0]-250)*1.5;y=135+q[1]*1.5
    color='#d56b38' if key in s['chains'] else '#0d918e'
    d.ellipse((x-11,y-11,x+11,y+11),fill=color,outline='white',width=1)
    d.text((x,y-1),str(i),font=font(14),fill='white',anchor='mm')
    tx=965;ty=150+(i-1)*46
    d.ellipse((tx,ty,tx+30,ty+30),fill=color);d.text((tx+15,ty+14),str(i),font=font(18),fill='white',anchor='mm')
    d.text((tx+44,ty),label,font=font(22),fill='#253e36')
d.text((40,370),'当前示例',font=font(24),fill='#183f35')
d.text((40,416),'近侧：画面左侧',font=font(21),fill='#253e36')
d.text((40,454),'远侧：画面右侧',font=font(21),fill='#253e36')
d.text((40,518),'不要按角色的',font=font(20),fill='#65746e')
d.text((40,553),'“自身左 / 右”混用。',font=font(20),fill='#65746e')
im.save(IMG/'05-anchors.png')

def figure(name,caption):
    data=base64.b64encode((IMG/name).read_bytes()).decode()
    mime='image/png' if name.endswith('.png') else 'image/jpeg'
    return f'<figure><img onclick="openManualImage(this)" tabindex="0" onkeydown="if(event.key===String.fromCharCode(13))openManualImage(this)" src="data:{mime};base64,{data}" alt="{html.escape(caption)}"><figcaption>{caption}（点击图片可放大；标注为阅读辅助。）</figcaption></figure>'

style='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;color:#213c34;background:#edf1eb;font:16px/1.85 "Microsoft YaHei",system-ui,sans-serif}header{padding:58px 7%;background:#173f35;color:#fff}header p{max-width:850px;color:#d6e7dc}h1{font-size:38px;line-height:1.3;margin:12px 0 20px}h2{font-size:27px;line-height:1.45;margin:0 0 24px}h3{font-size:20px;margin:26px 0 10px}main{max-width:1120px;margin:auto;padding:32px 28px 64px}section{background:white;border-radius:15px;padding:30px 36px;margin:22px 0;scroll-margin-top:20px}a{color:#087d70}header a{color:#dceec9}nav{display:flex;gap:14px;flex-wrap:wrap}nav a{padding:7px 12px;background:#ffffff12;border-radius:6px;text-decoration:none}small{letter-spacing:2px;color:#bbd2c4}p{margin:12px 0}ol,ul{padding-left:25px}li{margin:8px 0}.note{border-left:4px solid #d88c43;background:#fff5e7;padding:14px 18px;margin:18px 0}.good{border-left-color:#278a70;background:#eaf5ed}.route{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.route>div{background:#f1f5ef;padding:18px;border-radius:9px}table{border-collapse:collapse;width:100%;font-size:15px;margin:20px 0}th,td{border:1px solid #d6e1d8;padding:12px;vertical-align:top;text-align:left}th{background:#ecf3ec}figure{margin:22px 0}img{width:100%;height:auto;border:1px solid #dbe2dc;border-radius:8px}figcaption{font-size:13px;color:#63786e;line-height:1.6;padding-top:9px}.step{display:inline-block;background:#dfeee2;color:#175e49;padding:3px 10px;border-radius:5px;font-size:14px;margin-bottom:14px}code{background:#edf3ee;border-radius:4px;padding:2px 5px;color:#245549;overflow-wrap:anywhere}pre{background:#edf3ee;white-space:pre-wrap;padding:16px;border-radius:8px;font-size:14px}details{border-top:1px solid #e3e8e3;padding:12px 0}summary{cursor:pointer;font-weight:bold}.flow{background:#173f35;color:white;padding:18px 22px;border-radius:10px;line-height:2.2}.check{list-style:none;padding-left:0}.check li:before{content:"□ ";color:#278a70}footer{text-align:center;font-size:13px;color:#6a7c71;padding:20px}button{background:#f2ecd9;border:0;padding:10px 16px;border-radius:6px;color:#173f35;cursor:pointer;font:inherit}@media(max-width:750px){.route{display:block}.route>div{margin:12px 0}main{padding:14px}section{padding:23px 20px}h1{font-size:30px}table{font-size:13px}th,td{padding:7px}}@media print{@page{size:A4;margin:16mm}body{background:white;font-size:10pt;line-height:1.65}header{padding:20px;color:#173f35;background:white}header p,small{color:#4f685e}nav,.print{display:none}main{padding:0}section{padding:0;margin:25px 0;border-radius:0;break-before:page}h1{font-size:28pt}h2{font-size:20pt}h3{font-size:13pt}figure{break-inside:avoid}img{max-height:210mm;object-fit:contain}table{font-size:9pt}tr{break-inside:avoid}a{color:inherit}details{display:block}details>*{display:block}footer{display:none}}'''

content='''<header><small>WALULU · 操作手册 / 2026.11.20</small><h1>05 骨骼动作<br>从 AI 视频到 Spine 工程</h1><p>按当前实际版本编写。先选适合你的路线，再按编号操作。每一步注明你需要做什么、系统会做什么，以及何时可以进入下一步。</p><nav><a href="#routes">选择路线</a><a href="#quick">样板快速上手</a><a href="#import">新视频步骤</a><a href="#review">逐帧审核</a><a href="#export">导出验收</a><a href="#manual">人工负担与限制</a><a href="#faq">问题处理</a></nav><p class="print"><button onclick="window.print()">打印 / 另存为 PDF</button>　单文件内嵌图片，可离线阅读。</p></header><main>
<section id="routes"><h2>先选路线：不要从头重做已有的成果</h2><div class="route"><div><h3>A · 只想看 / 使用已验收动作</h3><p>使用 <b>pixel_sync_20261120</b> 样板副本。</p><p>无需重新拆件、点关节、逐帧确认。</p><a href="#quick">按快速路线操作 →</a></div><div><h3>B · 同一视频扩展其他帧</h3><p>重新导入原“右前行走.mp4”，复用起始帧标注，再追踪新帧。</p><p>新帧仍要检查和校正。</p><a href="#same">看同视频快捷方式 →</a></div><div><h3>C · 全新视频 / 全新角色</h3><p>先手工定义起始帧的七个部件和十四个标注点，再追踪。</p><p>这是当前人工最多的路线。</p><a href="#import">从步骤 1 开始 →</a></div></div><div class="note"><b>你看到的大量人工操作是现版本的真实限制。</b>目前是“人工建立起始结构 → 系统追踪与生成 → 人工校正审核”的半自动工具。尚未实现新角色的一键语义拆件、可靠姿态识别和异常帧自动筛选。</div><p>打开：<a href="http://127.0.0.1:8770/studio_v3/#spineRig">http://127.0.0.1:8770/studio_v3/#spineRig</a>。本手册截图来自当前真实界面，使用已有样板说明控件位置；截图中的“已审核”不代表你导入的新视频也已通过。</p></section>
<section id="quick"><span class="step">路线 A · 最少操作</span><h2>直接使用已验收“右前行走”</h2><ol><li>进入工作台的 <b>05 骨骼动画</b>。</li><li>点击顶部 <b>从验收样板创建</b>，建立独立副本；原验收目录不受影响。如果已有副本，可在下拉框选择后点<b>载入</b>。</li><li>进入 <b>④ 动画核查与导出</b>，点<b>保存并生成当前动画</b>，等待技术核查通过。</li><li>先播放检查；需要交付时点<b>导出真实 Spine 工程</b>，等待出现<b>下载当前版本 Spine 工程 ZIP</b>链接，再点击下载。</li></ol><div class="good note">只查看、播放、切换帧和显示骨骼，不会修改附件。不要为了使用已有样板，去重新描边或逐个点击审核按钮。</div><p>正式动画名是 <code>reference_cycle</code>。原样板包含的 <code>test_*</code> 是诊断动画，不用于判断正式行走效果。</p></section>
<section id="import"><span class="step">步骤 1 · 人工选范围，系统抽帧</span><h2>导入视频，截取一个短动作段</h2><ol><li>点击 <b>① 视频参考</b>。</li><li>在 <b>AI 视频</b> 选择电脑上的视频文件。此处是05自己的导入入口，不必先完成04；02/03中的历史视频不会自动成为本工程的输入。</li><li>填写<b>起始源帧</b>和<b>结束源帧（包含）</b>，然后点击<b>导入并提取原帧</b>。</li><li>确认左侧信息中的名称、尺寸、帧率，底部时间轴应显示所选源帧。</li></ol><p>帧号从 <b>0</b> 开始。63–85包含23帧，在24fps下是23/24秒的逐帧播放区间。每次最多120帧，视频文件最大96MB。</p><div class="note">先选短片段把流程跑通，再做完整步态。当前不会自动替你确定循环边界；末尾返回首帧可能跳变。85–90只是本轮复用验证片段，不是一套新验收的完整行走循环。</div>__REF__<p><b>图中：</b>① 已验收样板入口；② 视频文件；③ 帧范围；④ 导入与同视频标注入口。导入新视频后，七个部件和骨骼默认待审核。</p><h3 id="same">路线 B 的快捷方式：同视频起始标注</h3><ol><li>选择原“右前行走.mp4”，文件内容必须完全相同；重新转码或裁剪后的文件不满足条件。</li><li>起始帧选在 <b>63–85</b> 内。若想复用本轮示例，填85–90。</li><li>导入后点 <b>同视频载入起始标注草稿</b>。</li><li>系统只填入<b>起始帧</b>的轮廓遮罩和十四个标注点；检查后进入<a href="#track">步骤4追踪</a>。后续新帧不会自动获得验收状态。</li></ol></section>
<section id="parts"><span class="step">步骤 2 · 新视频需要人工建立起始拆件</span><h2>定义七个部件，先确认像素完整</h2><p>新视频路线C执行本步；路线B有起始标注时，先检查已有遮罩，缺陷处再重描。</p><ol><li>将时间轴停在<b>起始帧</b>，进入<b>② 图集拆件</b>。</li><li>在左侧选一个部件。当前默认七件：远侧手臂、远侧腿、近侧腿、躯干、裤衩、近侧手臂、头部。</li><li>显示模式选<b>源视频帧</b>，点<b>开始重描</b>，沿部件可见外缘逐点点击。</li><li>点<b>完成轮廓</b>。至少3个顶点，最多256个；系统按当前帧原像素裁切。点<b>取消描边</b>可放弃尚未完成的线。</li><li>切到<b>仅选中部件</b>，关闭<b>原图垫底</b>，检查轮廓、末端是否被切掉、是否带入背景；必要时用150%–300%放大。</li><li>再切<b>拆件原位组装</b>，检查肩部、裤衩/大腿和手脚的搭接。满意后点<b>确认此帧此部件</b>。对七件依次操作。</li></ol>__PARTS__<p><b>图中：</b>① 先选部件；② 选择查看模式并关闭垫图检查真实裁片；③ 重描、完成、确认；④ 切换源帧。截图仅显示远侧手臂，其余像素隐藏，不是角色缺失。</p><div class="note"><b>“重描”会替换当前部件在当前帧的完整轮廓，不是局部补一块。</b>目前没有刷子式加减遮罩、轮廓顶点拖动、孔洞编辑或单独的跨帧补丁移植面板。选错后可撤销；不要把这些尚未实现的功能理解为已有能力。</div><p>左侧图层<b>从后到前</b>排列；“图层前移”让部件更靠前，“图层后移”相反。当前顺序应用于整段工程，不是单帧遮挡动画。当前方向中“近侧”通常是画面左侧，“远侧”是画面右侧，不要混用角色自身左右。</p></section>
<section id="pose"><span class="step">步骤 3 · 人工定义关节，系统计算绑定</span><h2>标记十四个点，建立四条 IK 骨骼链</h2><ol><li>仍停在起始帧，进入<b>③ 骨骼 / IK</b>，显示模式选<b>源视频帧</b>并勾选<b>骨骼</b>。</li><li>在右侧下拉框选择关节点名称，再在原图对应位置<b>点击</b>。操作是“选点名 → 点画布”，不是拖动骨骼。</li><li>设置10个点：颈部、骨盆中心、近/远侧肩、近/远侧髋、近/远侧手端、近/远侧脚端。</li><li>再设置4个弯曲点：近/远侧肘、近/远侧膝。</li><li>检查肩→肘→手、髋→膝→脚的连线方向。全部完成后点<b>确认此帧骨骼</b>，再<b>保存工程</b>。</li></ol>__POSE__<p><b>图中：</b>① 选择要设置的点；② 确认、复制及追踪工具；③ 追踪会覆盖后续帧的提示；④ 逐帧定位。修改点后，该帧骨骼会恢复为待审核。</p>__ANCHORS__<table><tr><th>点组</th><th>怎么选</th><th>必须避免</th></tr><tr><td>肩 / 髋 / 骨盆</td><td>按身体结构选择一致的连接位置；遮挡处属于人工推定。</td><td>让点随衣服纹理或手臂遮挡漂到另一个部位。</td></tr><tr><td>手端 / 脚端</td><td>选择可稳定追踪的末端参考位置，各帧保持同一口径。</td><td>一帧选中心、下一帧跳到最外轮廓，或近远侧互换。</td></tr><tr><td>肘 / 膝</td><td>放在该链合理的弯曲侧；参考手脚的运动方向。</td><td>突然穿到链的另一侧；当前段不支持IK弯曲方向翻转。</td></tr></table><div class="note">当前面板编辑的是源姿势标注；完整蒙皮与IK效果要在“生成当前动画”后检查。系统会生成16根骨骼、4组双骨IK和网格权重，不需要你在这里手工画每个网格点。</div></section>
<section id="track"><span class="step">步骤 4 · 系统追踪草稿，人工决定是否重跑</span><h2>从检查好的起始帧追踪后续帧</h2><ol><li>确认当前帧已具备七件轮廓/遮罩，以及十四个骨骼标注点。</li><li>如果视频背景均匀，可勾选<b>均匀背景前景补全（仍只取原帧像素）</b>；复杂背景不要依赖它。</li><li>点击<b>从此帧追踪后续轮廓 / 锚点</b>，等待完成。系统会保存当前编辑，向后生成草稿，通常跳到下一帧供检查。</li><li>进入下一步逐帧检查。新草稿中的部件、骨骼都恢复为<b>待审核</b>。</li></ol><div class="note"><b>它会覆盖当前帧之后的全部轮廓与锚点。</b>不要刚修好后几帧，又从更早的帧重新追踪，否则会覆盖你的修正。只在确定要重新传播的帧开始追踪。当前页面可撤销本次追踪；不要依赖刷新后的撤销历史。</div><p>“前景补全”是从<b>当前源帧</b>重新识别露出的角色像素，再分配给邻近部件；不是AI补画，也不能恢复原视频根本没显示的背面。光流追踪可能跟错手脚或遮挡处，它的输出始终是草稿。</p></section>
<section id="review"><span class="step">步骤 5 · 当前最耗人工的环节</span><h2>按“这一帧的七件 → 这一帧骨骼 → 下一帧”审核</h2><div class="flow">定位源帧 → 单件检查 × 7 → 组装检查 → 确认7个部件<br>→ 检查 / 修正14个点 → 确认此帧骨骼 → 下一帧 → 保存</div><ol><li>点<b>下一帧</b>或拖动时间轴，检查底部显示的<b>源帧号</b>。</li><li>在②中逐个选择部件；关闭垫图，以“仅选中部件”查缺失，再以“拆件原位组装”查搭接。</li><li>发现缺陷：重描该帧该部件完整轮廓；修好后点<b>确认此帧此部件</b>。对该帧七件都确认。</li><li>切到③，对照原图检查十四个点。选错的点重新点击设置，再点<b>确认此帧骨骼</b>。</li><li>所有帧完成后，进度应为<b>审核完成 N/N 帧</b>。保存工程。</li></ol><p><b>“复制上一帧锚点（待审核）”</b>只复制十四个点，不复制部件、不追踪运动；静态部位接近时可作起点，但仍要修正并确认。</p><table><tr><th>重点部位</th><th>检查内容</th></tr><tr><td>裤衩 / 大腿</td><td>裆部轮廓有无残缺；腿有没有切走裤口；髋点有没有滑到裤衩中央；前后顺序是否合理。</td></tr><tr><td>远侧手臂</td><td>当前示例为画面右边较细的一只。肩点是否漂到手端；手是否漏切；是否混入躯干。</td></tr><tr><td>近侧手臂</td><td>肩根是否切断；手端是否跟错衣服纹理；肘的弯曲侧是否保持一致。</td></tr><tr><td>双脚</td><td>抬脚时新露出的轮廓是否完整；脚端近远侧有没有互换；源帧切换前后有无跳动。</td></tr></table><div class="note">当前没有“一键确认所有帧”。23帧需 23×7=161 次部件确认，再加23次骨骼确认，共184次。<b>确认按钮只记录审核，不会替你修复像素，也不代表最终视觉验收。</b>这部分重复操作需要后续产品优化。</div></section>
<section id="generate"><span class="step">步骤 6 · 系统生成，人工看结果</span><h2>生成同步动画，再做动态检查</h2><ol><li>进入<b>④ 动画核查与导出</b>。</li><li>点击<b>保存并生成当前动画</b>。当前版本要求每帧七个部件和骨骼都已确认，否则会提示未完成的帧。</li><li>系统自动裁片、打图集、创建骨骼/IK、计算蒙皮并生成同步时间轴。完成后画布切换到实际Spine运行时预览。</li><li>关闭<b>原图垫底</b>，先看真实蒙皮，避免原帧底图遮住缺失；再开关骨骼观察。</li><li>使用<b>播放 / 暂停</b>和<b>0.25×</b>慢放。暂停后分别查看<b>帧起点、帧内中点、切换前</b>，重点看裤裆、手脚和肩部。</li></ol>__EXPORT__<p><b>图中：</b>① 先生成；② 再导出；③ 数值核查提示；④ 时间轴、帧内位置、速度。图中显示的是已验收样板，不是对新素材的自动验收结论。</p><div class="good note">正确的当前模式：每个原帧内，附件和骨骼姿势同时保持；到了下一帧再同时切换。这样避免“骨骼继续运动、皮肤还停在上一帧”造成裂缝。它复现视频节奏，不是任意新姿势都能连续变形的通用皮肤。</div><p>若发现问题，回到②/③修改。<b>修改会使旧预览和旧下载失效</b>；重新确认相应项，再保存、生成、检查。技术核查通过只说明坐标与同步符合约束，不说明部件语义或动作美术已经合格。</p></section>
<section id="export"><span class="step">步骤 7 · 导出、下载、在 Spine 中验收</span><h2>最后下载真实 .spine 工程</h2><ol><li>当前动画生成并检查后，点<b>导出真实 Spine 工程</b>。</li><li>等待服务器调用Spine完成导入、回导与对比。看到导出成功后，点新出现的<b>下载当前版本 Spine 工程 ZIP</b>。单击导出按钮本身不会自动下载文件。</li><li>将ZIP完整解压，保留 <code>parts/</code>、图集和其他文件的相对位置。不要只取出一个 <code>.spine</code> 文件。</li><li>用Spine打开 <code>walk.spine</code>，在动画列表找到 <code>reference_cycle</code>。</li><li><b>点动画名称左侧的小圆点激活动画，再播放。</b>只选中名称不一定切换当前动画。复制样板中的 <code>test_*</code> 是测试动画，不是正式行走。</li><li>复查完整循环、脚部抬落、裤衩/大腿衔接、近远侧手臂。将发现的问题按源帧号记录，再回工作台修正。</li></ol><p>ZIP包含工程、运行时JSON、图集、原帧附件、来源记录及校验报告；新遮罩工程还带遮罩文件。当前导出以Spine 4.2.43为目标。</p><h3>保存与备份的区别</h3><ul><li><b>保存工程</b>：保存在本机 <code>studio_v3/pixel_projects/</code>，不是自动提交GitHub。</li><li><b>ZIP</b>：用于Spine验收及交付记录。当前05界面没有“导入工程ZIP恢复编辑”的按钮；若要保留可继续编辑的本机工程，应同时备份对应的工程目录。</li><li><b>撤销 / 重做</b>：主要用于当前页面中的编辑，不应当作跨会话版本恢复工具。</li></ul></section>
<section id="manual"><h2>为什么现在仍有很多人工？</h2><table><tr><th>阶段</th><th>系统已做</th><th>仍需要人工</th></tr><tr><td>视频</td><td>解码、连续抽帧、保留尺寸/帧率和来源。</td><td>选择可用动作和循环区间。</td></tr><tr><td>拆件</td><td>按轮廓裁片；追踪遮罩；均匀背景下补足新露出前景。</td><td>新角色的起始七件语义、复杂遮挡、缺失和误分配。</td></tr><tr><td>骨骼</td><td>传播标注草稿；生成16骨骼、4IK、网格权重。</td><td>起始十四点、遮挡点推定、跟踪漂移校正。</td></tr><tr><td>审核</td><td>记录每帧状态，阻止未审核输入生成。</td><td>逐帧查看、逐件确认。目前没有异常帧筛选和批量审核。</td></tr><tr><td>导出</td><td>同步动画、图集、真实Spine工程、回导检查和ZIP。</td><td>视觉与动作质量最终验收。</td></tr></table><p><b>本轮已解决的是流程与导出可靠性，尚未完成低人工成本的自动制作。</b>现在最耗时的不是Spine文件生成，而是起始结构定义、追踪错误校正和重复确认。</p><h3>减少人工的建议顺序（尚未实现）</h3><ol><li><b>先做待办导航：</b>自动定位未审核帧/部件，支持经过检查后的批量确认，减少184次重复点击。</li><li><b>再做异常检测：</b>标出手脚漂移、骨长突变、前景缺失和近远侧互换，把注意力集中到问题帧。</li><li><b>增加局部修整与关键帧传播：</b>允许只修边缘、只传播选中的点或部件，避免整段覆盖。</li><li><b>最后扩展新角色自动初始化：</b>自动预测七件和关节点，再由用户少量校正；必须用不同素材验证，不以当前样板推定成功。</li></ol><p>这份手册描述的是现版本真实操作；上面的改进方向不是已完成的功能，也不是要求你现在全部手工承担的长期方案。</p></section>
<section id="faq"><h2>常见问题：按提示处理</h2><table><tr><th>现象</th><th>处理方法</th></tr><tr><td>工作台地址打不开</td><td>先启动本机服务，命令见下方；需要服务运行才可编辑和导出。本手册HTML本身可离线打开。</td></tr><tr><td>同视频草稿按钮失败</td><td>确认文件内容就是原视频；起始帧在63–85。不同文件请走新视频路线。</td></tr><tr><td>提示某帧未完成审核</td><td>定位该源帧，在②确认7个部件，在③确认骨骼。只确认骨骼不够。</td></tr><tr><td>画面完整，但一关垫图就缺块</td><td>之前看到的是底图补齐的视觉效果。关垫图检查实际附件，修遮罩后重新生成。</td></tr><tr><td>提示骨骼弯曲方向翻转</td><td>检查肘/膝是否放错侧、手脚是否互换。当前工具不支持同段IK方向翻转，不要盲目挪点只为消除提示。</td></tr><tr><td>提示先保存并生成当前动画</td><td>输入有修改，或尚未生成；先完成审核，再点生成，之后导出。</td></tr><tr><td>均匀背景补全失败</td><td>四角背景不均匀或检测不到前景。关闭该选项并检查轮廓；复杂背景不要将它当通用抠图。</td></tr><tr><td>Spine有骨架但看起来不动</td><td>在动画列表点 <code>reference_cycle</code> 左侧圆点，然后播放；确认未停留在Setup/设置状态。</td></tr><tr><td>提示工程被另一页面更新</td><td>不要多页面同时编辑同一工程。先记录当前修改，再载入服务器最新版本后重做必要改动。</td></tr><tr><td>未找到Spine CLI</td><td>电脑需安装并授权Spine；配置 <code>SPINE_CLI</code> 指向可用CLI，再重启服务。</td></tr></table><h3>本机启动</h3><p>在解压工程的 <code>spine_workbench</code> 文件夹打开PowerShell：</p><pre>py -3 server_v3.py --host 127.0.0.1 --port 8770</pre><p>首次缺依赖时：</p><pre>py -3 -m pip install -r requirements-pixel.txt</pre><p>生成还需要Node.js；真实工程导出需要已授权的Spine 4.2.43 CLI。默认路径为 <code>E:/MyTools/Spine/Spine.com</code>，其他安装路径通过 <code>SPINE_CLI</code> 环境变量指定。</p><h3>交付前核对</h3><ul class="check"><li>我确认了正确的视频、源帧区间和角色方向。</li><li>我关闭垫图检查过真实附件，没有靠底图遮住缺失。</li><li>裤裆、远侧手、双脚的像素和关节点已检查。</li><li>我修改后重新生成过，没有下载旧版本。</li><li>Spine中已激活 reference_cycle，并检查播放和循环。</li></ul></section>
</main><footer>05骨骼动作操作手册 · 2026-11-20 · 依据当前工作台与已验收样板编写</footer>'''
for token,name,caption in [('__REF__','01-reference-marked.jpg','图1｜视频参考与三种入口'),('__PARTS__','02-parts-marked.jpg','图2｜单件查看、描边与确认'),('__POSE__','03-pose-marked.jpg','图3｜骨骼标注与后续追踪'),('__ANCHORS__','05-anchors.png','图4｜十四个标注点的位置示例'),('__EXPORT__','04-export-marked.jpg','图5｜生成、动态核查与导出')]:
    content=content.replace(token,figure(name,caption))
content+='''<dialog id=manualDialog style="width:95vw;max-width:1600px;border:0;border-radius:12px;padding:16px"><button onclick="document.getElementById('manualDialog').close()">关闭（Esc）</button><img id=manualZoom alt=放大图></dialog><script>function openManualImage(img){document.getElementById('manualZoom').src=img.src;document.getElementById('manualDialog').showModal()}</script>'''
document='<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>05 骨骼动作 · 图文操作手册</title><style>'+style+'</style></head><body>'+content+'</body></html>'
(HERE/'index.html').write_text(document,encoding='utf8')
print('Created',HERE/'index.html')
